<script setup>
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api} from '../api'
import {setCourseExperience} from '../composables/experience'
import AssignmentEditor from '../components/AssignmentEditor.vue'
import GradebookPanel from '../components/GradebookPanel.vue'
import {formatDate,toUtc} from '../utils/assignments'
const props=defineProps({boundCourse:{type:Object,default:null},embedded:Boolean})
const route=useRoute(),router=useRouter(),courses=ref([]),selected=ref(''),course=ref(null),data=ref(null),error=ref(''),busy=ref(false),quizEditor=ref(false),reportEditor=ref(false),weight=ref(1),form=ref({title:'',instructions:'',maxScore:100,weight:1,opensAt:'',dueAt:''})
const grades=computed(()=>!props.embedded && route.meta.assessmentGrades)
const staff=computed(()=>data.value?.staff)
async function load(){busy.value=true;error.value='';try{courses.value=props.boundCourse?[props.boundCourse]:await api('/courses');selected.value=props.boundCourse?.id || route.query.course || courses.value[0]?.id || '';course.value=courses.value.find(c=>c.id===selected.value);if(!course.value && selected.value)throw new Error('找不到你參與的課程。');setCourseExperience(course.value?.canPractice??null);if(course.value)data.value=await api(`/courses/${selected.value}/assessments`)}catch(e){error.value=e.message}finally{busy.value=false}}
async function change(){if((quizEditor.value||reportEditor.value)&&!confirm('確定放棄未儲存的評量設定？')){selected.value=course.value?.id||'';return;}quizEditor.value=false;reportEditor.value=false;await router.replace({path:route.path,query:{course:selected.value}});await load()}
async function createQuiz(input){busy.value=true;error.value='';try{const created=await api(`/courses/${selected.value}/quizzes`,{method:'POST',body:{assignment:input,weight:weight.value}});quizEditor.value=false;await router.push('/quizzes/'+created.id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function createReport(){busy.value=true;error.value='';try{const created=await api(`/courses/${selected.value}/reports`,{method:'POST',body:{...form.value,opensAt:toUtc(form.value.opensAt),dueAt:toUtc(form.value.dueAt)}});reportEditor.value=false;await router.push('/reports/'+created.id)}catch(e){error.value=e.message}finally{busy.value=false}}
function guard(){return !(quizEditor.value||reportEditor.value)||confirm('確定放棄未儲存的評量設定？')}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
onMounted(load)
</script>
<template><section v-if="!embedded" class="page-heading"><div><p class="eyebrow">ASSESSMENTS &amp; GRADES</p><h1>{{grades?'測驗／作業成績管理':'線上測驗與 PDF 作業'}}</h1><p class="muted">測驗由教師命題、學生線上作答；作業繳交 PDF 報告。客觀題自動批改，申論及 PDF 人工評分；教師確認後連動課程成績，不使用 AI 評分。</p></div></section><p v-if="error" class="error-box" role="alert">{{error}}</p><RouterLink v-if="!embedded && course" :to="`/courses/${course.id}?section=${grades?'grades':'assessments'}`" class="back-link">← 返回 {{course.title}}</RouterLink><label v-if="!embedded && courses.length">課程<select aria-label="評量課程" v-model="selected" @change="change"><option v-for="c in courses" :key="c.id" :value="c.id">{{c.code}} · {{c.title}}</option></select></label><nav v-if="!embedded" class="course-navigation" aria-label="測驗與作業功能"><RouterLink :to="{path:'/assessments',query:{course:selected}}">測驗與作業</RouterLink><RouterLink :to="{path:'/assessment-grades',query:{course:selected}}">測驗／作業成績管理</RouterLink></nav><GradebookPanel v-if="grades && course" :key="course.id" :course="course" /><template v-if="!grades && data && course"><div v-if="staff && course.status!=='archived'" class="studio-actions"><button class="button primary" @click="quizEditor=!quizEditor;reportEditor=false">建立線上／課後測驗</button><button class="button secondary" @click="reportEditor=!reportEditor;quizEditor=false">建立 PDF 報告作業</button></div><section v-if="quizEditor" class="surface form-surface"><label>成績權重<input v-model.number="weight" type="number" min="0.001" max="999999" step="0.001" /></label><AssignmentEditor quiz :course-id="course.id" :busy="busy" @save="createQuiz" @cancel="quizEditor=false" /></section><section v-if="reportEditor" class="surface form-surface"><h2>建立 PDF 報告作業</h2><form @submit.prevent="createReport"><fieldset :disabled="busy"><label>作業名稱<input v-model="form.title" required maxlength="200" /></label><label>作業說明<textarea v-model="form.instructions" maxlength="24000" rows="5"></textarea></label><div class="form-grid"><label>滿分<input v-model.number="form.maxScore" type="number" min="0.01" max="999999" step="0.01" required /></label><label>成績權重<input v-model.number="form.weight" type="number" min="0.001" max="999999" step="0.001" required /></label><label>開放時間<input v-model="form.opensAt" type="datetime-local" /></label><label>截止時間<input v-model="form.dueAt" type="datetime-local" /></label></div><button class="button primary">儲存作業草稿</button></fieldset></form></section><section class="surface form-surface"><h2>線上／課後測驗</h2><p class="muted">是非、單選、多選自動批改；申論由教師／助教評閱，確認發布後納入成績管理。</p><RouterLink v-for="q in data.quizzes" :key="q.id" :to="`/quizzes/${q.id}`" class="studio-case-card surface"><h3>{{q.title}}</h3><p>{{{draft:'草稿',published:'已發布',closed:'已關閉'}[q.status]}} · 權重 {{q.weight}} · 截止 {{formatDate(q.dueAt)}}</p></RouterLink><p v-if="!data.quizzes.length" class="empty-inline">目前沒有可見的線上測驗。</p></section><section class="surface form-surface"><h2>PDF 報告作業</h2><p class="muted">學生繳交 PDF，由教師／助教閱讀並給分；成績連動到同一份加權成績管理。</p><RouterLink v-for="r in data.reports" :key="r.id" :to="`/reports/${r.id}`" class="studio-case-card surface"><h3>{{r.title}}</h3><p>{{{draft:'草稿',published:'已發布',closed:'已關閉'}[r.status]}} · 權重 {{r.weight}} · 截止 {{formatDate(r.dueAt)}} <span v-if="!staff">· {{r.submitted?'已繳交':'未繳交'}}</span></p></RouterLink><p v-if="!data.reports.length" class="empty-inline">目前沒有可見的 PDF 作業。</p></section></template><p v-if="!busy && !courses.length" class="surface form-surface">尚未加入課程，請聯絡管理者。</p></template>
